 1	import { Router } from 'express';
 2	import multer from 'multer';
 3	import type { Env } from '../config/env.js';
 4	import { asyncHandler } from '../middleware/asyncHandler.js';
 5	import { authMiddleware, requireRoles } from '../middleware/auth.js';
 6	import { complaintController } from '../controllers/complaintController.js';
 7	import { prisma } from '../lib/prisma.js';
 8	import { listPublicIssues } from '../services/complaintService.js';
 9	
10	const upload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 5 * 1024 * 1024 } });
11	
12	export function complaintRouter(env: Env): Router {
13	  const r = Router();
14	  const c = complaintController(env);
15	  const auth = authMiddleware(env);
16	
17	  r.get(
18	    '/public',
19	    asyncHandler(async (req, res) => {
20	      const page = Number(req.query.page ?? 1);
21	      const pageSize = Math.min(100, Number(req.query.pageSize ?? 50));
22	      res.json(await listPublicIssues(page, pageSize));
23	    }),
24	  );
25	
26	  r.get(
27	    '/meta/categories',
28	    asyncHandler(async (_req, res) => {
29	      res.json({
30	        categories: await prisma.complaintCategory.findMany({
31	          where: { isActive: true },
32	          include: { subcategories: true },
33	        }),
34	      });
35	    }),
36	  );
37	
38	  r.use(auth);
39	  r.get('/', asyncHandler(c.list));
40	  r.post('/', requireRoles('CITIZEN', 'ADMIN'), asyncHandler(c.create));
41	  r.get('/geocode', asyncHandler(c.geocode));
42	  r.get('/:id', asyncHandler(c.get));
43	  r.post('/:id/status', asyncHandler(c.status));
44	  r.post('/:id/assign', requireRoles('OFFICER', 'ADMIN'), asyncHandler(c.assign));
45	  r.post('/:id/comments', asyncHandler(c.comment));
46	  r.post('/:id/verify', requireRoles('CITIZEN'), asyncHandler(c.verify));
47	  r.post('/:id/reopen', asyncHandler(c.reopen));
48	  r.post('/:id/resolve', asyncHandler(c.resolve));
49	  r.post('/:id/media', upload.single('file'), asyncHandler(c.upload));
50	  r.get('/:id/media/:mediaId', asyncHandler(c.media));
51	  return r;
52	}

