 26	export function complaintController(env: Env) {
 27	  return {
 28	    create: async (req: Request, res: Response) => {
 29	      const body = parseJson(createComplaintSchema, req.body);
 30	      const complaint = await createComplaint(env, req.user!, body);
 31	      res.status(201).json({ complaint });
 32	    },
 33	    list: async (req: Request, res: Response) => {
 34	      const page = parseJson(paginationSchema, req.query);
 35	      const result = await listComplaints(req.user!, {
 36	        ...page,
 37	        status: req.query.status as ComplaintStatus | undefined,
 38	        priority: req.query.priority as Priority | undefined,
 39	        q: req.query.q as string | undefined,
 40	        categoryId: req.query.categoryId as string | undefined,
 41	        areaId: req.query.areaId as string | undefined,
 42	        assigned: req.query.assigned as string | undefined,
 43	        sla: req.query.sla as string | undefined,
 44	      });
 45	      res.json(result);
 46	    },
 47	    get: async (req: Request, res: Response) => {
 48	      const complaint = await loadAuthorizedComplaint(req.user!, req.params.id);
 49	      res.json({ complaint });
 50	    },
 51	    duplicates: async (req: Request, res: Response) => {
 52	      const items = await findDuplicates(req.params.id);
 53	      res.json({ items });
 54	    },
 55	    status: async (req: Request, res: Response) => {
 56	      const body = parseJson(statusChangeSchema, req.body);
 57	      const complaint = await transitionStatus(req.user!, req.params.id, body.status, body.note);
 58	      res.json({ complaint });
 59	    },
 60	    assign: async (req: Request, res: Response) => {
 61	      const body = parseJson(assignSchema, req.body);
 62	      const complaint = await assignComplaint(req.user!, req.params.id, body);
 63	      res.json({ complaint });
 64	    },
 65	    comment: async (req: Request, res: Response) => {
 66	      const body = parseJson(commentSchema, req.body);
 67	      const comment = await addComment(req.user!, req.params.id, body.body, body.visibility);
 68	      res.status(201).json({ comment });
 69	    },
 70	    verify: async (req: Request, res: Response) => {
 71	      const body = parseJson(verifySchema, req.body);
 72	      const complaint = await verifyResolution(req.user!, req.params.id, body.resolved, body.reason);
 73	      res.json({ complaint });
 74	    },
 75	    reopen: async (req: Request, res: Response) => {
 76	      const complaint = await transitionStatus(
 77	        req.user!,
 78	        req.params.id,
 79	        'REOPENED',
 80	        typeof req.body?.reason === 'string' ? req.body.reason : undefined,
 81	      );
 82	      res.json({ complaint });
 83	    },
 84	    resolve: async (req: Request, res: Response) => {
 85	      const complaint = await transitionStatus(req.user!, req.params.id, 'RESOLVED', req.body?.note);
 86	      res.json({ complaint });
 87	    },
 88	    upload: async (req: Request, res: Response) => {
 89	      const file = req.file;
 90	      if (!file) {
 91	        res.status(400).json({ error: { code: 'VALIDATION_ERROR', message: 'Image required' } });
 92	        return;
 93	      }
 94	      const kind = (req.body.kind as MediaKind | undefined) ?? 'EVIDENCE';
 95	      const media = await saveComplaintMedia(env, req.user!, req.params.id, file, kind);
 96	      res.status(201).json({ media });
 97	    },
 98	    media: async (req: Request, res: Response) => {
 99	      const { bytes, mimeType } = await readMedia(env, req.user!, req.params.mediaId);
100	      res.setHeader('Content-Type', mimeType);
101	      res.send(bytes);
102	    },
103	    geocode: async (req: Request, res: Response) => {
104	      const q = String(req.query.q ?? '');
105	      const geo = createGeocoder(env);
106	      const results = q ? await geo.search(q) : [];
107	      res.json({ results });
108	    },
109	  };
110	}

