11	
12	export function complaintRouter(env: Env): Router {
13	  const r = Router();
14	  const c = complaintController(env);
15	  const auth = authMiddleware(env);
16	
17	  r.get(
18	    '/public',
19	    asyncHandler(async (req, res) => {
20	      const page = Number(req.query.page ?? 1);
21	      const pageSize = Math.min(100, Number(req.query.pageSize ?? 50));
