406	function overlapScore(a: string, b: string): number {
407	  const ta = new Set(a.toLowerCase().split(/\W+/).filter((w) => w.length > 3));
408	  const tb = new Set(b.toLowerCase().split(/\W+/).filter((w) => w.length > 3));
409	  if (ta.size === 0 || tb.size === 0) return 0;
410	  let inter = 0;
411	  for (const w of ta) if (tb.has(w)) inter += 1;
412	  return inter / Math.min(ta.size, tb.size);
413	}
