104	export function resolveAssignmentEffect(
105	  to: ComplaintStatus,
106	  from: ComplaintStatus,
107	  role: Role,
108	): Prisma.ComplaintAssignmentUpdateManyMutationInput | undefined {
109	  if (to === 'ACCEPTED') return { status: 'ACCEPTED', acceptedAt: new Date() };
110	  if (to === 'RESOLVED') return { status: 'COMPLETED', completedAt: new Date() };
111	  if (to === 'ASSIGNED') return { status: 'REASSIGNED' };
112	  // A field team sending ASSIGNED back to UNDER_REVIEW is a decline, unlike an
113	  // officer moving it there to re-review, which must not stamp DECLINED.
114	  if (to === 'UNDER_REVIEW' && from === 'ASSIGNED' && role === 'FIELD_WORKER') {
115	    return { status: 'DECLINED' };
116	  }
117	  return undefined;
118	}
