 1	import { MEDIA_KINDS, type Role } from '@civicfix/shared';
 2	import { ValidationError } from '../lib/errors.js';
 3	
 4	export type MediaKind = (typeof MEDIA_KINDS)[number];
 5	
 6	const ROLE_MEDIA_KINDS: Record<Role, readonly MediaKind[]> = {
 7	  CITIZEN: ['EVIDENCE', 'REOPEN'],
 8	  FIELD_WORKER: ['BEFORE', 'AFTER', 'EVIDENCE', 'RESOLUTION'],
 9	  OFFICER: ['EVIDENCE', 'RESOLUTION'],
10	  ADMIN: ['EVIDENCE', 'BEFORE', 'AFTER', 'RESOLUTION', 'REOPEN'],
11	};
12	
13	export function isMediaKindAllowed(role: Role, kind: MediaKind): boolean {
14	  return ROLE_MEDIA_KINDS[role].includes(kind);
15	}
16	
17	export function parseMediaKind(raw: unknown): MediaKind {
18	  if (raw === undefined || raw === null || raw === '') return 'EVIDENCE';
19	  if (typeof raw !== 'string') {
20	    throw new ValidationError('Unsupported media kind');
21	  }
22	  const match = MEDIA_KINDS.find((kind) => kind === raw);
23	  if (!match) {
24	    throw new ValidationError(`Unsupported media kind: ${raw}`);
25	  }
26	  return match;
27	}

