26	
27	  async reverse(lat: number, lng: number): Promise<GeocodeResult | null> {
28	    try {
29	      const url = new URL('https://nominatim.openstreetmap.org/reverse');
30	      url.searchParams.set('lat', String(lat));
31	      url.searchParams.set('lon', String(lng));
32	      url.searchParams.set('format', 'jsonv2');
33	      const res = await fetch(url, { headers: { 'User-Agent': this.userAgent } });
34	      if (!res.ok) return new NoneGeocoder().reverse(lat, lng);
35	      const data = (await res.json()) as { display_name?: string };
36	      return {
37	        address: data.display_name ?? `${lat}, ${lng}`,
38	        latitude: lat,
39	        longitude: lng,
40	      };
41	    } catch (err) {
42	      logger.warn({ err }, 'geocode_reverse_failed');
43	      return new NoneGeocoder().reverse(lat, lng);
44	    }
45	  }
46	
47	  async search(query: string): Promise<GeocodeResult[]> {
48	    try {
49	      const url = new URL('https://nominatim.openstreetmap.org/search');
50	      url.searchParams.set('q', query);
51	      url.searchParams.set('format', 'jsonv2');
52	      url.searchParams.set('limit', '5');
53	      const res = await fetch(url, { headers: { 'User-Agent': this.userAgent } });
54	      if (!res.ok) return [];
55	      const data = (await res.json()) as Array<{ display_name: string; lat: string; lon: string }>;
56	      return data.map((d) => ({
57	        address: d.display_name,
58	        latitude: Number(d.lat),
59	        longitude: Number(d.lon),
60	      }));
61	    } catch (err) {
62	      logger.warn({ err }, 'geocode_search_failed');
63	      return [];
64	    }
65	  }
66	}
